package ai.xzkj.recruitment.localconnector;
import ai.xzkj.recruitment.audit.AuditService;import ai.xzkj.recruitment.auth.*;import ai.xzkj.recruitment.common.ApiException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service class LocalConnectorOfflineDrillService{private final LocalConnectorService connectors;private final LocalConnectorOfflineDrillRepository drills;private final CurrentUserService users;private final AuditService audit;LocalConnectorOfflineDrillService(LocalConnectorService c,LocalConnectorOfflineDrillRepository d,CurrentUserService u,AuditService a){connectors=c;drills=d;users=u;audit=a;}@Transactional OfflineDrillResponse report(String authorization,OfflineDrillReport report){BrowserDevice device=connectors.authenticate(authorization);if(!"FIXTURE_ONLY".equals(report.evidenceSource()))throw new ApiException(HttpStatus.CONFLICT,"DRILL_SOURCE_REJECTED","只接受本地 fixture 演练证据");if(report.beforeDigest().equals(report.afterDigest()))throw new ApiException(HttpStatus.CONFLICT,"DRILL_STATE_UNCHANGED","演练前后状态摘要不能相同");if("FAILED".equals(report.outcome())&&(report.failureReason()==null||report.failureReason().isBlank()))throw new ApiException(HttpStatus.BAD_REQUEST,"DRILL_FAILURE_REASON_REQUIRED","失败演练必须说明原因");LocalConnectorOfflineDrill drill=drills.save(new LocalConnectorOfflineDrill(device,report,Instant.now()));audit.systemSuccess("RECORD_CONNECTOR_OFFLINE_DRILL","LOCAL_CONNECTOR_OFFLINE_DRILL",drill.getId(),device.getBossAccount().getDisplayName(),report.actionType()+" · "+report.outcome()+" · FIXTURE_ONLY；不会提升真实页面能力");return OfflineDrillResponse.from(drill);}@Transactional(readOnly=true)List<OfflineDrillResponse> list(){SystemUser u=users.requireCurrentUser();return drills.findTop100ByOrderByCreatedAtDesc().stream().filter(x->u.getRole()==UserRole.SYSTEM_ADMIN||u.getCompanyScopes().stream().anyMatch(c->c.getId().equals(x.getDevice().getBossAccount().getCompany().getId()))).map(OfflineDrillResponse::from).toList();}}
